 showEditor('편성된 조 수정',`<p class="note">회원별 배정할 조를 선택하세요. 각 조 ${g.grouping.group_size}명을 맞춰 저장하면 됩니다.</p><div id="groupeditpreview" class="calc"></div>${groups.map((group,i)=>group.map(m=>`<label>${esc(m.name)} · 핸디 ${m.handicap}<select name="group_${esc(m.id)}">${groups.map((_,j)=>`<option value="${j}" ${i===j?'selected':''}>${j+1}조</option>`).join('')}</select></label>`).join('')).join('')}`,f=>api('game-groupings','PUT',{id:g.id,groups:groups.map((_,i)=>groups.flat().filter(m=>Number(f.get('group_'+m.id))===i).map(m=>m.id))}),()=>{const savedGame=state.games.find(item=>item.id===g.id);if(savedGame?.grouping)showGroupingPopup(savedGame)});
